operations.schema:
input SetAccountInput {
  address: String
  name: String
  provider: String
}

operations.reducer:
const i = action.input;
if (i.address !== undefined) state.account.address = i.address;
if (i.name !== undefined) state.account.name = i.name;
if (i.provider !== undefined) state.account.provider = i.provider;

const i = action.input;
const externalId = i.externalId.trim();
if (!/^[a-z0-9_-]+:.+/i.test(externalId))
  throw new InvalidExternalIdError(`External id must be namespaced, e.g. gmail:18f3a, got "${i.externalId}"`);
if (state.externalId && state.externalId !== externalId)
  throw new ExternalIdMismatchError(`This document holds ${state.externalId}, not ${externalId}`);
const mailboxes = (list: { address: string; name?: string | null }[] | null | undefined) => (list ?? []).map((m) => ({ address: m.address, name: m.name ?? null }));
state.externalId = externalId;
state.messageId = i.messageId ?? null;
state.threadId = i.threadId ?? null;
state.inReplyTo = i.inReplyTo ?? null;
state.references = [...(i.references ?? [])];
state.subject = i.subject ?? null;
state.from = mailboxes(i.from);
state.to = mailboxes(i.to);
state.cc = mailboxes(i.cc);
state.bcc = mailboxes(i.bcc);
state.replyTo = mailboxes(i.replyTo);
state.sentAt = i.sentAt ?? null;
state.receivedAt = i.receivedAt ?? null;
state.text = i.text ?? null;
state.html = i.html ?? null;
state.snippet = i.text ? i.text.replace(/\s+/g, " ").trim().slice(0, 160) : null;
state.headers = (i.headers ?? []).map((h) => ({ key: h.key, value: h.value }));
state.labels = [...new Set((i.labels ?? []).map((l) => l.trim()).filter((l) => l !== ""))];
state.source = i.source ?? state.source;
state.capturedAt = i.capturedAt;

const i = action.input;
const fileName = i.fileName.trim();
if (fileName === "") throw new InvalidFileNameError("An attachment needs a file name");
if (state.attachments.some((a) => a.id === i.id || (a.ref === i.ref && a.fileName === fileName)))
  throw new DuplicateAttachmentError(`Attachment ${fileName} is already on the message`);
state.attachments.push({
  id: i.id,
  ref: i.ref,
  fileName,
  mimeType: i.mimeType ?? null,
  sizeBytes: i.sizeBytes ?? null,
  contentId: i.contentId ?? null,
  inline: i.inline ?? false,
});

const index = state.attachments.findIndex((a) => a.id === action.input.id);
if (index === -1) throw new AttachmentNotFoundError(`Attachment ${action.input.id} not found`);
state.attachments.splice(index, 1);

const labels = action.input.labels.map((raw) => raw.trim());
if (labels.some((label) => label === ""))
  throw new InvalidLabelError("A label cannot be empty");
for (const label of labels) {
  if (!state.labels.includes(label)) state.labels.push(label);
}

const labels = action.input.labels.map((raw) => raw.trim());
const missing = labels.find((label) => !state.labels.includes(label));
if (missing !== undefined)
  throw new LabelNotFoundError(`No label "${missing}" on the message`);
state.labels = state.labels.filter((label) => !labels.includes(label));
